import {isSupplierForm,validateSupplierForm} from './form-validation.js';
// Production controller. The demo controller is disabled by pina-runtime=live.
// Every financial mutation is authenticated, authorised and persisted by PHP/MySQL.
import {marketingView,publicLegalCopy,icon,logo,header,footer,btn} from './app.js';
import {$,esc,money,date,dateTime,openModal,closeModal,installModalKeys} from './legacy-ui.js';
import {companyFieldsHTML,categoryLabels,CATEGORIES} from './merchant.js';
import {createAdmin} from './admin.js';
import {createStaffAccess} from './staff-access.js';
import {createWorkflows} from './workflows.js';
let config=null,state=null,currentIssuer='',tab='overview',busy=false,pollTimer=null;
const API='/api/gift/';
const adminUi=createAdmin({api,esc,icon,logo,btn,money,date:dateTime,openModal,closeModal,status,client:()=>state.client,csrf:()=>config.csrf,refreshConfig:async()=>{config=await api('config/');}});
const workUi=createWorkflows({api,esc,btn,money,date:dateTime,openModal,closeModal,status,issuer:()=>currentIssuer,client:()=>state.client,refresh:route,download,csrf:()=>config.csrf});
const staffAccess=createStaffAccess({api,esc,logo,status,refresh:route});
async function api(path,data){const response=await fetch(API+path,{method:data===undefined?'GET':'POST',credentials:'same-origin',headers:data===undefined?{}:{'Content-Type':'application/json','X-CSRFToken':config.csrf},...(data===undefined?{}:{body:JSON.stringify(data)})});let result;try{result=await response.json();}catch{throw Error('Не удалось прочитать ответ сервера. Обновите данные перед повтором операции.');}if(!response.ok)throw Object.assign(Error(result.error||result.message||'Операция не выполнена'),{status:response.status});return result;}
function status(message,error=false){const el=$('#toast');el.textContent=message;el.classList.add('show');el.setAttribute('role',error?'alert':'status');clearTimeout(el.hideTimer);el.hideTimer=setTimeout(()=>el.classList.remove('show'),6000);}
async function sync(){state=await api('state/');if(!state.issuers.some(i=>i.id===currentIssuer))currentIssuer=state.issuers[0]?.id||'';}
function partner(id){return config.catalog.find(p=>p.id===id);}
function cards(){return (state?.orders||[]).flatMap(order=>order.cards.map(card=>({order,card})));}
function cardLabel(o,c){if(c.refund_status==='paid')return 'Возврат выполнен';if(c.refund_status==='requested')return 'Запрошен возврат';if(o.payment_status!=='confirmed')return o.payment_status==='partial'?'Оплачен частично':o.payment_requested_at?'В обработке: ожидаем подтверждения оплаты':'Заказ не оплачен';if(c.redemption_status==='redeemed')return 'Принята поставщиком';if(['unknown','pending'].includes(c.redemption_status))return 'Проверяем приём';if(c.issuance_status==='issued')return 'Код создан';if(['pending','unknown'].includes(c.issuance_status))return 'Проверяем создание';if(c.issuance_status==='cancelled')return 'Карта отменена';return 'Можно создать код';}
function publicPartners(){return config.catalog.map(p=>({id:p.id,name:esc(p.name),issuer:esc(p.company.name),country:esc(p.country),category:esc(categoryLabels(p.program)||'Карты компаний'),mark:'КР',color:'sage',icon:'merchant',description:esc(p.program.description||p.program.goods||'Товары и услуги зарубежной компании'),use:esc(p.program.goods||'По условиям программы')}));}
function publicClean(html){const doc=new DOMParser().parseFromString(html,'text/html');doc.querySelectorAll('.art-demo,.demo-caption,.application-note').forEach(e=>e.remove());doc.querySelectorAll('.catalog-note').forEach(e=>e.textContent='Перед оплатой проверьте эмитента, страну, срок действия и условия использования карты.');doc.querySelectorAll('.catalog-toolbar .tabs').forEach(e=>e.remove());doc.querySelectorAll('.mini-card-title small').forEach(e=>e.textContent='Пример отображения карты');doc.querySelectorAll('.merchant-entry').forEach(e=>e.href='#/merchant/company');doc.querySelectorAll('[data-action=partner]').forEach(e=>e.dataset.action='live-partner');doc.querySelectorAll('[data-action=support]').forEach(e=>{e.dataset.action='contact';});doc.querySelectorAll('a').forEach(a=>{if(a.textContent.includes('демо-кабинет'))a.innerHTML='Открыть личный кабинет '+icon('arrow');});doc.querySelectorAll('.legal-note').forEach(e=>e.textContent='Pina Market реализует карты от имени и за счёт компаний-эмитентов. Товары и услуги предоставляет выбранная компания. Условия карты и сведения об эмитенте раскрываются до оплаты.');doc.querySelectorAll('.hero-footnote,.note,.checkline span,.faq-list p').forEach(e=>{e.innerHTML=e.innerHTML.replace('В прототипе реальные реквизиты отключены.','').replace('Понимаю, что заявка демонстрационная.','').replace('Понимаю, что это демонстрация формы.','').replace('В прототипе данные остаются в этом браузере. Реальное сообщение не отправляется.','Заявка будет направлена команде Pina Market.');});doc.querySelectorAll('#merchant-form button').forEach(b=>b.innerHTML=b.innerHTML.replace('демо-заявку','заявку'));if(!config.catalog.length){const list=doc.querySelector('#partner-list');if(list)list.innerHTML='<div class="panel empty">Готовим первые программы карт.<br>Каталог откроется после подключения компаний и согласования условий.<br><a class="text-link" href="#/business">Вы поставщик? Обсудим подключение '+icon('arrow')+'</a></div>';}return doc.body.innerHTML;}
function frame(title,subtitle,content,merchant=false){const nav=merchant?[['overview','redemption','Приём карты'],['registry','orders','Реестр активаций'],['settlements','reports','Баланс и расчёты'],['company','contract','Реквизиты и договор'],['requests','support','Запросы и документы']]:[['overview','home','Обзор'],['cards','gift-card','Мои карты'],['orders','orders','Заказы'],['support','support','Поддержка'],['docs','contract','Документы'],['profile','customer','Профиль']];return `<div class="shell ${merchant?'merchant-shell':''}"><aside class="sidebar"><a class="logo" href="#/">${logo()}</a><nav class="nav" aria-label="Личный кабинет">${nav.map(([id,i,n])=>`<a href="#/${merchant?'merchant':'account'}/${id}" class="${tab===id?'active':''}">${icon(i)}<span>${n}</span></a>`).join('')}</nav><div class="side-bottom"><div class="side-box"><a href="mailto:mail@pina.market">mail@pina.market</a></div><a href="#/">На главную</a><a href="#/${merchant?'account':'merchant'}">${merchant?'Кабинет покупателя':'Кабинет поставщика'}</a>${state?.client.staff?'<a href="#/admin">Управление программой</a>':''}${btn('Выйти','logout','textbtn')}</div></aside><main class="main" id="main"><header class="topbar"><span class="crumb">${merchant?'Для бизнеса':'Личный кабинет'} / ${title}</span><a class="mobile-logo" href="#/">${logo()}</a><span class="profile"><span>${esc(state?.client.email)}<small>ID ${state?.client.id}</small></span></span></header><div class="page-head"><div><p class="eyebrow">Pina Market</p><h1>${title}</h1><p>${subtitle}</p></div>${merchant?'<a class="btn small" href="#/catalog">Каталог карт</a>':btn('Добавить карту','live-add-card','small')}</div>${content}</main></div>`;}
function cardTile(o,c){const ready=o.payment_status==='confirmed'&&c.issuance_status==='not_issued'&&c.refund_status==='none';return `<article class="account-card"><div class="account-card-top"><div class="issuer-avatar sage">${icon('gift-card')}</div><div><h3>${esc(o.snapshot.name)}</h3><small>Заказ № ${o.id}</small></div></div><strong class="card-amount">${money(Number(c.nominal_minor)/100)}</strong><span class="badge">${cardLabel(o,c)}</span><div class="card-bottom">${o.payment_status!=='confirmed'?btn(o.payment_status==='partial'?'Доплатить по заказу':'Оплатить заказ','live-pay-order','small',String(o.id)):ready?btn('Выпустить — создать код','live-issue','small',c.id):c.issuance_status==='issued'&&c.redemption_status==='not_redeemed'&&c.refund_status==='none'?btn('Показать код','live-code','outline small',c.id):btn('Подробнее','live-card','outline small',c.id)}${ready||c.issuance_status==='issued'&&c.redemption_status==='not_redeemed'&&c.refund_status==='none'?btn('Подробнее и возврат','live-card','textbtn small',c.id):''}</div></article>`;}
function ordersView(){return `<div class="panel order-list">${state.orders.map(o=>`<article class="order-row"><span class="order-row-icon">${icon('orders')}</span><span class="order-row-main"><b>Заказ № ${o.id}</b><small>${esc(o.snapshot.name)} · ${o.cards.length} карт · ${date(o.created_at+'Z')}</small></span><span class="order-row-status ${o.payment_status==='confirmed'?'paid':''}">${o.payment_status==='confirmed'?'Оплачен':o.payment_status==='partial'?'Оплачен частично':o.payment_requested_at?'В обработке — ожидаем подтверждения оплаты':'Ожидает оплаты'}</span><span class="order-row-amount"><b>${money(Number(o.total_minor)/100)}</b></span><div class="order-actions">${o.payment_status==='confirmed'?'':btn(o.payment_status==='partial'?'Доплатить по заказу':'Оплатить заказ','live-pay-order','small',String(o.id))}${btn('Инструкция и реквизиты','live-invoice','outline small',String(o.id))}</div></article>`).join('')||'<div class="empty">Пока нет заказов. Нажмите «Добавить карту», выберите поставщика и номиналы.</div>'}</div>`;}

async function buyerView(){if(!state)await sync();let content='';if(tab==='orders')content=ordersView();else if(tab==='profile')content=await workUi.profile();else if(tab==='support')content=await workUi.cases(false)+`<section class="panel"><h2>Обращения на возврат</h2>${state.refunds.map(r=>`<article class="claim"><h3>Возврат ${esc(r.id.slice(0,8))}</h3><p>${esc(r.reason)}</p><p>${esc(r.resolution||'Обращение рассматривается')}</p>${btn('Карта и документы возврата','live-card','outline small',r.card_id)}</article>`).join('')||'<p>Нет обращений на возврат.</p>'}</section>`;else if(tab==='docs')content=`<div class="doc-list">${[['terms','Публичная оферта'],['refund','Возврат'],['guarantees','Гарантии и ответственность'],['privacy','Обработка данных']].map(([id,n])=>`<a class="doc-link" href="#/legal/${id}">${n}${icon('arrow')}</a>`).join('')}</div>`;else content=`${tab==='overview'?`<section class="overview-main"><p>Ваш следующий шаг</p><h2>Оплаченные карты —<br>в вашем кабинете.</h2><span>Создайте код, когда будете готовы передать его выбранному поставщику.</span></section><div class="subhead"><h2>Ваши карты</h2></div>`:''}<div class="account-card-grid">${cards().map(({order:o,card:c})=>cardTile(o,c)).join('')||'<div class="panel empty">У вас пока нет карт. Выберите программу зарубежной компании в каталоге.</div>'}</div>${tab==='overview'?'<div class="subhead"><h2>Заказы</h2></div>'+ordersView():''}`;const title={overview:'Обзор',cards:'Мои карты',orders:'Заказы',support:'Поддержка',docs:'Документы',profile:'Профиль'}[tab]||'Обзор';return frame(title,'Карты выбранных компаний, заказы и обращения',content);}
function issuerSelector(){return state.issuers.length>1?`<div class="merchant-context"><label for="live-issuer">Компания</label><select id="live-issuer">${state.issuers.map(i=>`<option value="${i.id}" ${i.id===currentIssuer?'selected':''}>${esc(i.name)}</option>`).join('')}</select></div>`:'';}
function companyForm(){const i=state.issuers.find(i=>i.id===currentIssuer),co=i?.company||{};return `<div class="merchant-company-layout"><section class="panel"><p class="eyebrow">Один рамочный договор</p><h2>Реквизиты и подключение</h2><p>Заполните сведения о компании. Документ получит номер, реквизиты обеих сторон и согласованные условия.</p><p>Статус: <b>${esc(({draft:'Договор не загружен',agent_signed:'Подписан Pina Market',review:'Договор на проверке',approved:'Договор принят'})[i?.contract_status]||'Реквизиты не заполнены')}</b></p>${i?`${btn('Скачать договор в PDF','live-contract-prepare','outline full',i.id)}<p class="note">Подпись Pina Market добавляется только после её утверждения. Если она ещё не настроена, документ отмечен как проект.</p><hr><form id="live-upload" class="fields"><div class="field"><label for="live-contract-file">Подписанный договор</label><input id="live-contract-file" name="file" type="file" required accept=".pdf,.docx"></div><p class="note">Загрузите подписанный PDF или DOCX до 10 МБ. Договор можно получить любым способом: предварительно скачивать его из кабинета не требуется. После загрузки документ проверит команда Pina Market.</p><button class="btn full">Загрузить и отправить договор</button><p class="form-error" role="alert" hidden></p></form>`:'<p>После сохранения реквизитов здесь появятся договор и загрузка подписанного экземпляра.</p>'}</section><form id="live-company" novalidate class="panel form-panel fields"><h2>Данные компании</h2><p class="note">Укажите страну регистрации, категорию и фактическое место исполнения за пределами РФ.</p><p class="notice">Типовые условия карт уже заполнены. Проверьте их и при необходимости измените перед сохранением. Реквизиты и фактический адрес заполните данными своей компании.</p>${companyFieldsHTML(co,{prefix:'live-co-',disabled:['active','paused'].includes(i?.status),program:i?.program||{}})}<label class="checkline"><input type="checkbox" required name="territoryConfirmed"><span>Проверил сведения и фактическое исполнение за пределами РФ. Получение товара или услуги в РФ и электронные услуги по этой программе не предусмотрены.</span></label><div class="field"><label for="co-fulfillment">Фактический адрес передачи товара или оказания услуги</label><input id="co-fulfillment" name="fulfillmentAddress" required maxlength="500" value="${esc(co.fulfillmentAddress||'')}" ${['active','paused'].includes(i?.status)?'disabled':''}></div><p class="note">Юридический адрес указывайте здесь только при фактической выдаче по этому адресу. Получение товара или услуги в РФ и электронные услуги в эту программу не входят.</p><button class="btn full" ${['active','paused'].includes(i?.status)?'disabled':''}>Сохранить реквизиты</button><p class="form-error" role="alert" hidden></p></form></div>`;}
async function merchantView(){if(!state)await sync();const i=state.issuers.find(i=>i.id===currentIssuer);if(!i)return frame('Кабинет поставщика','Подключение выполняет администратор','<section class="panel"><h2>Доступ поставщика ещё не назначен</h2><p>Ваш аккаунт зарегистрирован как покупатель. После проверки заявки администратор подключит компанию и назначит роль поставщика.</p><a href="#/business/application" class="btn">Оставить заявку на подключение</a></section>',true);let content=issuerSelector();if(tab==='company')content+=companyForm();else if(tab==='overview')content+=`<div class="merchant-dashboard"><section class="panel redeem-panel"><p class="eyebrow">Приём карты</p><h2>Примите код<br>в счёт заказа клиента.</h2><form id="live-activate" class="fields"><div class="field"><label for="live-code">Код сертификата</label><input id="live-code" name="code" required pattern="[A-Z0-9]{20}" maxlength="20" autocomplete="off"></div><div class="field"><label for="live-buyer">ФИО покупателя</label><input id="live-buyer" name="buyer" required maxlength="180"></div><div class="field"><label for="live-reference">Номер договора или заказа</label><input id="live-reference" name="contract" required maxlength="200"></div><div class="field"><label for="live-basis">Основание</label><select id="live-basis" name="basis"><option value="advance">Аванс по договору</option><option value="order_payment">Оплата конкретного заказа</option></select></div><div class="field"><label for="live-subject">Что оплачивает покупатель: товар или услуга</label><input id="live-subject" name="purchaseSubject" required maxlength="500" placeholder="Например, подбор автомобиля по договору №…"></div><div class="field"><label for="live-holder">ФИО другого держателя, если отличается от покупателя</label><input id="live-holder" name="holderName" maxlength="180"></div><div class="field"><label for="live-performance">Исполнение основной покупки</label><select id="live-performance" name="performance"><option value="future">Товар ещё не передан / услуга ещё не оказана</option><option value="claimed_performed">Товар передан / услуга оказана, есть первичный документ</option></select></div><div class="field"><label for="live-performance-document">Реквизиты документа исполнения, если покупка исполнена</label><input id="live-performance-document" name="performanceDocument" maxlength="500" placeholder="Акт или накладная: номер и дата"></div><div class="notice">Место исполнения берётся из условий оплаченного заказа. Приём кода сам по себе не подтверждает передачу товара или оказание услуги. Первичные документы хранит поставщик и предоставляет по запросу.</div><button class="btn full" ${!['active','paused'].includes(i?.status)?'disabled':''}>Проверить и принять карту</button><p class="form-error" role="alert" hidden></p></form></section><section class="panel"><h2>${esc(i.name)}</h2><p>Статус подключения: ${esc(({draft:'Заполните реквизиты',review:'Ожидает подтверждения программы',active:'Программа подтверждена',paused:'Новые продажи приостановлены'})[i.status]||i.status)}</p>${!['active','paused'].includes(i.status)?'<p class="notice">Проверьте реквизиты и условия карт. Команда Pina Market настроит торговую точку и подтвердит программу.</p><a class="btn full" href="#/merchant/company">Реквизиты и условия карт</a>':''}<a class="text-link" href="#/merchant/registry">Реестр принятых карт ${icon('arrow')}</a><a class="text-link" href="#/merchant/settlements">Баланс и расчёты ${icon('arrow')}</a></section></div>`;else if(tab==='registry')content+=await workUi.registry();else if(tab==='requests')content+=await workUi.cases(true);else content+=await workUi.settlements(balanceView);return frame({overview:'Приём карты',registry:'Реестр активаций',settlements:'Баланс и расчёты',company:'Реквизиты и договор',requests:'Запросы и документы'}[tab]||'Кабинет поставщика','Карты, банковские расчёты и подтверждающие документы',content,true);}
function balanceView(provider){const b=Array.isArray(provider?.balances)?provider.balances.find(x=>x.currency_code==='RUB'):provider;if(!b||b.balance===undefined)return '<div class="notice">Баланс платформы временно недоступен. Реестры расчётов доступны ниже.</div>';return `<div class="merchant-stat-grid"><article class="summary-stat"><span>Доступно · RUB</span><strong>${money(Number(b.balance))}</strong></article><article class="summary-stat"><span>Зарезервировано · RUB</span><strong>${money(Number(b.frozen_balance||0))}</strong></article></div>`;}
function auth(){openModal(`<div class="modal-icon">${icon('email-verified')}</div><h2>Вход и регистрация</h2><p class="intro">Пришлём одноразовую ссылку на вашу почту. Пароль не нужен.</p><form id="live-auth" class="fields"><div class="field"><label for="live-email">Email</label><input id="live-email" name="email" type="email" required maxlength="254" autocomplete="email"></div><label class="checkline"><input type="checkbox" required name="accepted"><span>Мне исполнилось 18 лет. С <a href="#/legal/terms" target="_blank" rel="noopener">публичной офертой</a> ознакомился и принимаю её условия.</span></label><label class="checkline"><input type="checkbox" required><span>Ознакомлен с <a href="#/legal/privacy" target="_blank" rel="noopener">обработкой данных</a>.</span></label><button class="btn full">Получить ссылку для входа</button><p class="form-error" role="alert" hidden></p></form>`,'Вход в Pina Market');}
function selectCardSupplier(){
 const options=CATEGORIES.filter(([code])=>config.catalog.some(p=>(p.program.categories||[p.program.category]).includes(code)));
 openModal(`<h2>Добавить карту</h2><p>Выберите категорию и поставщика. В одном заказе будут карты одной компании.</p><form id="live-supplier-choice" class="fields"><div class="field"><label>Категория<select name="category" id="live-card-category"><option value="">Все категории</option>${options.map(([code,name])=>`<option value="${code}">${esc(name)}</option>`).join('')}</select></label></div><div class="field"><label>Поставщик<select name="issuerId" id="live-card-supplier" required><option value="">Выберите поставщика</option>${config.catalog.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label></div><p class="note" data-supplier-empty ${config.catalog.length?'hidden':''}>Пока нет доступных программ карт.</p><button class="btn full" ${config.catalog.length?'':'disabled'}>Выбрать номиналы</button><p class="form-error" hidden role="alert"></p></form>`,'Добавление карты');
}
function orderLineHTML(p,nominal=p.program.nominals[0]){return `<div class="order-card-line" data-order-line><div class="field"><label>Номинал карты<select name="cardNominal" required>${p.program.nominals.map(n=>`<option value="${n}" ${n===nominal?'selected':''}>${money(n/100)}</option>`).join('')}</select></label></div><div class="field"><label>Количество<input name="cardQuantity" type="number" required min="1" max="10" step="1" value="1"></label></div>${btn('Убрать','live-remove-order-line','textbtn small')}</div>`;}
function orderValues(form){const p=partner(form.dataset.issuer),values=[];for(const row of form.querySelectorAll('[data-order-line]')){const nominal=Number(row.querySelector('[name=cardNominal]').value),quantity=Number(row.querySelector('[name=cardQuantity]').value);if(!p?.program.nominals.includes(nominal)||!Number.isInteger(quantity)||quantity<1||quantity>10)throw Error('Проверьте номинал и количество карт.');values.push(...Array(quantity).fill(nominal));}if(!values.length||values.length>10)throw Error('В одном заказе должно быть от 1 до 10 карт.');return values;}
function updateOrderTotal(form){delete form.dataset.key;const total=form.querySelector('[data-order-total]');try{const values=orderValues(form);total.textContent=money(values.reduce((sum,n)=>sum+n,0)/100);}catch{total.textContent='Проверьте состав заказа';}}
async function requestOrderPayment(id,cashLocationId){const details=await api('orders/payment-request/',{orderId:Number(id),...(cashLocationId?{cashLocationId}: {})});await sync();await route();await invoice(id,details);}
async function payOrder(id){const locations=config.cashLocations||[];if(locations.length<=1)return requestOrderPayment(id,locations[0]?.id);openModal(`<h2>Где оплатить заказ № ${esc(id)}</h2><form id="live-payment-order" data-order="${esc(id)}" class="fields"><div class="field"><label>Касса банка<select name="cashLocationId" required>${locations.map(l=>`<option value="${esc(l.id)}">${esc(l.name)} — ${esc(l.address)}</option>`).join('')}</select></label></div><button class="btn full">Получить инструкцию по оплате</button><p class="form-error" hidden role="alert"></p></form>`,'Оплата заказа');}

async function partnerDialog(id){const p=partner(id);if(!p)throw Error('Программа недоступна');openModal(`<p class="eyebrow">Подарочная карта</p><h2>${esc(p.name)}</h2><dl class="receipt"><dt>Эмитент</dt><dd>${esc(p.company.name)}<br>${esc(p.company.address)}<br>Рег. № ${esc(p.company.reg)}<br>${esc(p.company.email)}</dd><dt>Страна исполнения</dt><dd>${esc(p.program.use_country||'За пределами РФ')}</dd><dt>Место получения товара или услуги</dt><dd>${esc(p.program.fulfillment_address||'Адрес ещё не согласован')}</dd><dt>Условия территории</dt><dd>Получение товара, доставка покупателю и оказание услуг в России по этой карте не предусмотрены.</dd><dt>Выпуск по запросу</dt><dd>${esc(p.program.issue_deadline)}</dd><dt>Срок запроса</dt><dd>${esc(p.program.request_deadline)}</dd><dt>Срок действия</dt><dd>${esc(p.program.validity||String(p.program.expires_seconds/86400)+' дней')}</dd><dt>Погашение</dt><dd>${esc(p.program.redemption)}</dd><dt>Возврат</dt><dd>${esc(p.program.refund)}</dd></dl><a href="${esc(p.program.rules)}" target="_blank" rel="noopener" class="text-link">Правила программы ${icon('arrow')}</a><form id="live-order" data-issuer="${p.id}" class="fields"><h3>Карты в заказе</h3><div data-order-lines>${orderLineHTML(p)}</div>${btn('Добавить ещё номинал','live-add-order-line','outline small')}<div class="order-total"><span>Сумма заказа</span><strong data-order-total>${money(p.program.nominals[0]/100)}</strong></div><p class="note">Каждая карта будет выпущена отдельно по вашему запросу после подтверждения оплаты заказа оператором.</p><label class="checkline"><input type="checkbox" required name="accepted"><span>Проверил эмитента, ограничения и условия программы. С <a href="#/legal/terms" target="_blank" rel="noopener">офертой</a> ознакомился, принимаю её и подтверждаю заказ с обязанностью оплаты. Комиссию банка за перевод, если она есть, банк сообщает отдельно.</span></label>${!config.salesEnabled?'<p class="notice" role="status">Приём новых заказов пока не открыт. Вернитесь позже или свяжитесь с Pina Market.</p>':''}<button class="btn full" ${!config.salesEnabled||!p.program.fulfillment_address?'disabled':''}>Добавить карты в заказ</button><p class="form-error" role="alert" hidden></p></form>`,'Условия и заказ карты',true);}
async function invoice(id,details=null){const o=state.orders.find(o=>String(o.id)===String(id));details??=await api('orders/invoice/?orderId='+encodeURIComponent(id));openModal(`<p class="eyebrow">Заказ № ${o.id} · ID покупателя ${details.clientId||state.client.id}</p><h2>${o.payment_status==='confirmed'?'Заказ оплачен':'Оплата заказа на выпуск карт'}</h2><strong class="detail-amount">${money(Number(details.dueMinor??o.total_minor)/100)}</strong><dl class="receipt">${Object.entries(details.fields).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl><div class="notice">${esc(details.instructions)}</div><p class="note">${o.payment_status==='confirmed'?'Оплата подтверждена. Выпустите код нужной карты в разделе «Мои карты».':o.payment_requested_at?'Заказ в обработке. Ожидаем подтверждения поступления оператором. Получение инструкции само по себе не подтверждает оплату.':'Заказ ещё не оплачен. Нажмите «Оплатить заказ», чтобы получить инструкцию для выбранной кассы.'}</p>${o.payment_status!=='confirmed'&&!o.payment_requested_at?btn('Оплатить заказ','live-pay-order','full',String(id)):''}${btn('Сохранить инструкцию','live-invoice-download','outline full',String(id))}${btn('Оферта по этому заказу','live-order-terms','textbtn',String(id))}<a class="btn outline full" href="#/account/cards">Мои карты</a>`,'Оплата заказа',true);}

async function cardDetail(id){openModal(await workUi.card(id),'Карта и возврат');}
async function route(){closeModal(true);clearTimeout(pollTimer);const entryHash=!location.hash&&location.pathname.replace(/\/+$/,'')==='/admin'?'#/admin':location.hash;const parts=entryHash.replace(/^#\/?/,'').split('?')[0].split('/');const page=parts[0]||'';tab=parts[1]||'overview';try{
 if(page==='verify'){const r=await api('auth/verify/',{token:parts[1]});config.csrf=r.csrf;await sync();if(state.client.staff){location.replace('/admin/');return;}history.replaceState(null,'',state.issuers.length?'#/merchant':'#/account');return route();}
 if(page==='legal'){const id=parts[1]||'terms';let d;if(id==='terms')d={title:'Публичная оферта',body:config.offer.content.map(i=>i.table?'<div class="table-wrap"><table>'+i.table.map(r=>'<tr>'+r.map(c=>'<td>'+esc(c).replace(/\n/g,'<br>')+'</td>').join('')+'</tr>').join('')+'</table></div>':/^\d+\s/.test(i.text)?'<h2>'+esc(i.text)+'</h2>':'<p>'+esc(i.text)+'</p>').join('')};else if(id==='privacy')d={title:'Обработка персональных данных',body:'<p>Pina Market LLC обрабатывает email, сведения об учётной записи, заказах, банковских поступлениях и обращениях для заключения и исполнения договора, учёта и защиты прав. Для приёма карты эмитент указывает ФИО покупателя и ссылку на договор или заказ.</p><p>Поставщик получает сведения, необходимые для своей покупки и расчётов. Данные не включаются в публичный реестр. Секретные коды защищаются и доступны только в предусмотренном сценарии. Паспорт по правилам банковского перевода проверяет банк.</p><p>Расчётные подтверждения и необходимые документы хранятся в пределах применимых обязательных сроков, указанных в договоре. Вопросы об обработке и правах субъектов направляйте на mail@pina.market. Отдельные согласия запрашиваются, когда они необходимы по закону; акцепт оферты не заменяет все такие согласия.</p>'};else d=await publicLegalCopy(id);$('#app').innerHTML=header()+`<main class="wrap legal-page" id="main"><a class="back-link" href="#/">← На главную</a><h1>${d.title}</h1><article>${d.body}</article></main>`+footer();$('.legal-note').textContent='Pina Market LLC · Реализация карт от имени и за счёт эмитентов.';return;}
 if(['account','merchant','admin'].includes(page)){try{await sync();}catch(e){if(e.status===401||e.status===403){$('#app').innerHTML=publicClean(await marketingView('home',publicPartners()));auth();return;}throw e;}if(page==='account'&&parts.length===1&&state.issuers.length&&!state.client.staff){history.replaceState(null,'','#/merchant');return route();}if(page==='admin'){if(!state.client.staff)throw Error('Недостаточно прав');const gate=await staffAccess.gate();if(gate!==null){$('#app').innerHTML=gate;return;}$('#app').innerHTML=await adminUi.render(location.hash);}else $('#app').innerHTML=page==='merchant'?await merchantView():await buyerView();if(cards().some(x=>['pending','unknown'].includes(x.card.issuance_status)||['pending','unknown'].includes(x.card.redemption_status)))pollTimer=setTimeout(()=>{if(document.visibilityState==='visible'&&$('#modal').hidden&&!document.activeElement?.matches('input,textarea,select'))route();},10000);}
 else{$('#app').innerHTML=publicClean(await marketingView(page==='business'?'business':'home',publicPartners()));const anchor=['catalog','how','faq'].includes(page)?page:page==='business'&&parts[1]==='application'?'application':null;if(anchor)requestAnimationFrame(()=>document.getElementById(anchor)?.scrollIntoView());}
 }catch(e){$('#app').innerHTML=`<main class="wrap legal-page" id="main"><h1>Не удалось открыть страницу</h1><p>${esc(e.message)}</p>${btn('Повторить загрузку','reload','outline')}<a class="text-link" href="#/">На главную ${icon('arrow')}</a></main>`;}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;e.preventDefault();const {action,id}=b.dataset;try{
 if(action.startsWith('otp-'))return await staffAccess.click(action);if(action.startsWith('work-'))return await workUi.click(action,id);if(action==='close'){adminUi.cancel();return closeModal();}if(action.startsWith('admin-'))return await adminUi.click(action.slice(6),id);if(action==='auth')return auth();if(action==='reload')return route();if(action==='menu'){const n=$('.mobile-links');n.hidden=!n.hidden;b.setAttribute('aria-expanded',String(!n.hidden));return;}if(action==='live-partner')return partnerDialog(id);if(action==='contact')return openModal('<h2>Связаться с Pina Market</h2><p class="intro">По заказам и картам: <a href="mailto:mail@pina.market">mail@pina.market</a>. Поставщикам доступна форма подключения на главной странице.</p>','Контакты');if(action==='logout'){await fetch('/api/logout/',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRFToken':config.csrf},body:'{}'});state=null;location.hash='/';return;}
 if(action==='live-contract-prepare'){b.disabled=true;const r=await api('documents/prepare/',{issuerId:id});const a=document.createElement('a');a.href=r.downloadUrl;a.download='';a.click();await sync();return;}
 if(action==='live-order-terms'){const o=await api('orders/terms/?orderId='+encodeURIComponent(id));openModal('<h2>Оферта по вашему заказу</h2><p>'+esc(o.version)+'</p><article>'+o.content.map(i=>i.table?'<div class="table-wrap"><table>'+i.table.map(r=>'<tr>'+r.map(c=>'<td>'+esc(c)+'</td>').join('')+'</tr>').join('')+'</table></div>':'<p>'+esc(i.text).replace(/\n/g,'<br>')+'</p>').join('')+'</article>','Условия заказа',true);return;}
 if(action==='live-add-card')return selectCardSupplier();
 if(action==='live-pay-order'){b.disabled=true;return await payOrder(id);}
 if(action==='live-add-order-line'){const f=document.querySelector('#live-order');if(f.querySelectorAll('[data-order-line]').length>=10)throw Error('В одном заказе не более 10 карт.');f.querySelector('[data-order-lines]').insertAdjacentHTML('beforeend',orderLineHTML(partner(f.dataset.issuer)));updateOrderTotal(f);return;}
 if(action==='live-remove-order-line'){const f=b.closest('form');if(f.querySelectorAll('[data-order-line]').length===1)throw Error('Оставьте хотя бы одну карту в заказе.');b.closest('[data-order-line]').remove();updateOrderTotal(f);return;}
 if(action==='live-invoice')return invoice(id);if(action==='live-card')return cardDetail(id);
 if(action==='live-issue'){openModal(`<h2>Создать код карты?</h2><p class="intro">Код предназначен только для выбранного поставщика. Передавайте его, когда будете готовы оплатить ваш заказ.</p>${btn('Создать код','live-confirm-issue','full',id)}`,'Создание кода');return;}
 if(action==='live-confirm-issue'){b.disabled=true;await api('cards/issue/',{cardId:id});closeModal();await sync();await route();status('Запрос принят. Проверяем результат создания кода.');return;}
 if(action==='live-code'){b.disabled=true;const r=await api('cards/code/?cardId='+encodeURIComponent(id));openModal(`<h2>Код вашей карты</h2><div class="code-box"><span>Передавайте только выбранному поставщику</span><code>${esc(r.code)}</code></div><p class="note">Поддержка не запрашивает ваш код.</p>`,'Код карты');return;}
 if(action==='live-refund'){openModal(`<h2>Обратиться за возвратом</h2><p class="intro">Создание кода или его приём поставщиком сами по себе не отменяют ваши законные права.</p><form id="live-refund-form" data-card="${id}" class="fields"><div class="field"><label for="live-reason">Причина</label><textarea id="live-reason" name="reason" required minlength="10" maxlength="3000"></textarea></div><button class="btn full">Отправить требование</button><p class="form-error" hidden role="alert"></p></form>`,'Возврат');return;}
 if(action==='live-invoice-download'){const x=await api('orders/invoice/?orderId='+encodeURIComponent(id)),text='Pina Market — счёт по заказу '+id+'\n'+Object.entries(x.fields).map(([k,v])=>k+': '+v).join('\n')+'\n'+x.instructions;download(new Blob([text],{type:'text/plain;charset=utf-8'}),'Pina-invoice-'+id+'.txt');return;}
 if(action==='live-registry-csv'){let rows=[],page=1;for(;page<=1000;page++){const r=await api('merchant/registry/?issuerId='+currentIssuer+'&page='+page);rows.push(...r.items);if(r.items.length<100)break;}const quote=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"';const csv='\ufeff'+[['Карта','Покупатель','Договор','Номинал RUB','Статус'],...rows.map(r=>[r.card_id,r.buyer_name,r.contract_reference,Number(r.nominal_minor)/100,r.status])].map(r=>r.map(quote).join(';')).join('\r\n');download(new Blob([csv],{type:'text/csv;charset=utf-8'}),'Pina-registry.csv');return;}
 if(action==='live-settlement-ack'){openModal(`<h2>Подтвердите полученный перевод</h2><form id="live-ack-form" data-settlement="${id}" class="fields"><div class="field"><label for="live-ack-amount">Фактически получено, ₽</label><input id="live-ack-amount" name="amount" required type="number" min="0.01" step="0.01"></div><div class="field"><label for="live-ack-ref">Подтверждение банка получателя</label><input id="live-ack-ref" name="bankReference" required maxlength="150"></div><label class="checkline"><input type="checkbox" required><span>Сверил банковское поступление с реестром.</span></label><button class="btn full">Подтвердить получение</button><p class="form-error" hidden role="alert"></p></form>`,'Подтверждение расчёта');}
 }catch(err){if(err.status===428&&err.message.includes('аутентификатор'))await route();else status(err.message,true);}finally{if(b.isConnected)b.disabled=false;}});
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('submit',async e=>{const f=e.target;if(!f.matches('form'))return;e.preventDefault();if(isSupplierForm(f)&&!validateSupplierForm(f))return;if(busy)return;busy=true;const d=Object.fromEntries(new FormData(f)),button=f.querySelector('button:not([type]),button[type=submit]'),error=f.querySelector('.form-error');if(button)button.disabled=true;try{
 if(f.dataset.staffAccess){await staffAccess.submit(f,d);}
 else if(f.dataset.workForm){await workUi.submit(f,d);}
 else if(f.dataset.adminForm){await adminUi.submit(f,d);}
 else if(f.id==='live-auth'){const r=await api('auth/request/',{email:d.email,accepted:!!d.accepted,offerVersion:config.offer.version});openModal('<h2>Проверьте почту</h2><p class="intro">'+esc(r.message)+'</p>','Ссылка отправлена');}
 else if(f.id==='merchant-form'){const r=await api('enquiries/',{...d,consent:!!d.consent});f.reset();status(r.message);}
 else if(f.id==='live-supplier-choice'){await partnerDialog(d.issuerId);}
 else if(f.id==='live-payment-order'){await requestOrderPayment(f.dataset.order,d.cashLocationId);}
 else if(f.id==='live-order'){if(!state){await sync().catch(()=>{});if(!state){auth();return;}}const key=f.dataset.key||(f.dataset.key=crypto.randomUUID());const o=await api('orders/',{key,issuerId:f.dataset.issuer,cards:orderValues(f),accepted:!!d.accepted,offerVersion:config.offer.version});await sync();closeModal();location.hash='/account/orders';await route();status('Заказ № '+o.id+' сохранён. Нажмите «Оплатить заказ», чтобы получить инструкцию.');}
 else if(f.id==='live-company'){const nominals=[...f.querySelectorAll('[name=nominals]:checked')].map(e=>Number(e.value));if(!nominals.length)throw Error('Выберите хотя бы один номинал карты.');const r=await api('merchant/company/',{issuerId:currentIssuer,company:{...d,nominals,categories:[...f.querySelectorAll('[name=categories]:checked')].map(e=>e.value),territoryConfirmed:!!d.territoryConfirmed}});currentIssuer=r.issuerId;await sync();await route();status('Реквизиты и программа карт сохранены. Теперь подготовьте договор для подписания.');}
 else if(f.id==='live-upload'){const file=f.querySelector('input[type=file]').files[0];if(!file||file.size>10*1024*1024)throw Error('Загрузите файл до 10 МБ');const body=new FormData();body.set('issuerId',currentIssuer);body.set('file',file);const response=await fetch(API+'documents/upload/',{method:'POST',credentials:'same-origin',headers:{'X-CSRFToken':config.csrf},body});const r=await response.json();if(!response.ok)throw Error(r.error||'Не удалось загрузить документ');await sync();await route();status('Экземпляр получен и передан на проверку.');}
 else if(f.id==='live-activate'){await api('merchant/activate/',{...d,issuerId:currentIssuer});f.reset();status('Запрос приёма зарегистрирован. Результат появится в реестре.');location.hash='/merchant/registry';}
 else if(f.id==='live-refund-form'){await api('refunds/',{cardId:f.dataset.card,reason:d.reason});closeModal();await sync();location.hash='/account/support';status('Требование зарегистрировано.');}
 else if(f.id==='live-ack-form'){await api('merchant/settlements/ack/',{...d,settlementId:f.dataset.settlement});closeModal();await route();status('Получение перевода подтверждено. Остаток платформы будет сверен вручную.');}
 else if(f.classList.contains('admin-merchant-form')){try{await api('admin/merchant-settings/',{...d,scopeId:f.dataset.scope,identityVerified:!!d.identityVerified});}finally{const keyField=f.querySelector('[name=apiKey]');if(keyField)keyField.value='';}await route();status('Настройки мерчанта проверены и сохранены.');}
 else if(f.classList.contains('admin-bank-form')){await api('admin/bank-confirm/',{...d,orderId:Number(f.dataset.order)});await route();status('Банковское поступление учтено.');}
 }catch(err){if(error?.isConnected){error.textContent=err.message;error.hidden=false;}else status(err.message,true);}finally{busy=false;if(button?.isConnected)button.disabled=false;}});
document.addEventListener('change',e=>{if(e.target.closest('#live-order')&&['cardNominal','cardQuantity'].includes(e.target.name))updateOrderTotal(e.target.form);if(e.target.id==='live-card-category'){const options=config.catalog.filter(p=>!e.target.value||(p.program.categories||[p.program.category]).includes(e.target.value)),form=e.target.form;form.querySelector('[name=issuerId]').innerHTML='<option value="">Выберите поставщика</option>'+options.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');form.querySelector('button').disabled=!options.length;form.querySelector('[data-supplier-empty]').hidden=!!options.length;}if(e.target.name==='country'){const target=e.target.form?.querySelector('[name=fulfillmentCountry]');if(target&&!target.value)target.value=e.target.value;}if(e.target.id==='live-issuer'){currentIssuer=e.target.value;route();}});
window.addEventListener('hashchange',route);document.addEventListener('visibilitychange',()=>{if(document.hidden&&$('#modal code'))closeModal(true);});
installModalKeys();
try{config=await api('config/');await route();}catch(e){$('#app').innerHTML=`<main class="wrap legal-page"><h1>Pina Market</h1><p>${esc(e.message)}</p><p>Карточная программа пока недоступна. Поддержка: mail@pina.market.</p></main>`;}
